// India Map State Paths and Geocoded City Coordinates
// Self-contained high-performance vector projection for client origin heatmap

export interface StatePath {
  id: string;
  name: string;
  path: string;
}

export interface CityCoordinate {
  name: string;
  canonicalName: string;
  state: string;
  lat: number;
  lng: number;
}

export const MAP_DIMENSIONS = {
  width: 600,
  height: 680,
  minLng: 68.0,
  maxLng: 97.6,
  minLat: 7.0,
  maxLat: 37.5,
};

// Mercator projection mapping Lat/Lng to SVG coordinates
export function projectCoordinates(lng: number, lat: number): { x: number; y: number } {
  const { width, height, minLng, maxLng, minLat, maxLat } = MAP_DIMENSIONS;
  const x = ((lng - minLng) / (maxLng - minLng)) * width;
  
  const latRad = (lat * Math.PI) / 180;
  const mercN = Math.log(Math.tan(Math.PI / 4 + latRad / 2));
  const minLatRad = (minLat * Math.PI) / 180;
  const maxLatRad = (maxLat * Math.PI) / 180;
  const minMerc = Math.log(Math.tan(Math.PI / 4 + minLatRad / 2));
  const maxMerc = Math.log(Math.tan(Math.PI / 4 + maxLatRad / 2));
  const y = height - ((mercN - minMerc) / (maxMerc - minMerc)) * height;
  
  return {
    x: Math.round(x * 10) / 10,
    y: Math.round(y * 10) / 10,
  };
}

